import{_ as t,o,c as s,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/20-所谓“依恋悖论”.md","filePath":"books/attached/20-所谓“依恋悖论”.md","lastUpdated":1794316978000}'),n={name:"books/attached/20-所谓“依恋悖论”.md"};function d(l,a,_,c,i,p){return o(),s("div",null,[...a[0]||(a[0]=[e("h3",{id:"所谓-依恋悖论",tabindex:"-1"},[r("所谓“依恋悖论” "),e("a",{class:"header-anchor",href:"#所谓-依恋悖论","aria-label":'Permalink to "所谓“依恋悖论”"'},"​")],-1),e("p",null,"早在脑成像技术得以发展以前，约翰·鲍尔比就知道，人们之所以需要一个人来共同生活，是基因使然，而无关乎我们有多么的自爱或者说感觉到独处有多么充实。他发现，一旦我们选定了那个人，这种感情是非常特别，非常强有力甚至超乎我们的可控范围。一种新的行为范式由此产生，无论我们之前有多么独立，多么不愿意依赖他人，这种行为范式都会势不可挡地出现。一旦我们选定那个伴侣，依恋就不再遵从我们的意愿，它必然会来势汹汹，不可磨灭。那种不含任何甘愿示弱与患得患失的优雅恋爱关系，听上去的确很棒，但是却有违我们的本能。两人结合成为一个共同体，的确是人类在进化过程中获取生存优势的有效途径，而这也就意味着两人会在感情上共甘苦。两个人融为一体，成了彼此的一部分，因此两人也会不惜一切代价来珍惜彼此；而正因为两人都为对方倾其所有，那么两个人的生存能力也都相应增加了。",-1),e("p",null,"虽然说人们在面对这种强大的力量时，有着各式各样的处理方式，安全型与焦虑型依恋风格的人，会去接受这种力量，而回避型的人却一心想要抑制这种力量。不过，这三种依恋风格的人，都无疑是需要亲密关系的。不过，在第6章会提到很多实验，它们都证明回避型依恋风格的人，虽然有着依恋需求，但是会竭力地抑制这种需求。",-1),e("p",null,"那么，这一切是不是就意味着要想在亲密关系中获得快乐，就必须要跟伴侣形影不离，以至于放弃事业或者朋友，以及其他生活中的重要方面呢？当然不是。相反，要想更好地独立涉足社会，我们更应该有一个可以依靠的伴侣。而这也就是所谓的“依恋悖论”。最开始，人们可能会觉得这个悖论在逻辑上讲不通。若是全身心依靠另一半，我们又怎能变得愈发独立呢？其实成人依恋理论的中心思想，简言之就是如此：若是你想要踏上幸福与独立共存的道路，你就该找到那个对的人，并且与之相伴，携手前行。当你明白了这一点，你也就抓住了依恋理论的精髓所在。为了更好地阐释这个主旨，让我们将目光转向孩提时代，也就是依恋开始的地方。虽然说成人依恋与儿童依恋并不尽然相同，但是如果你对儿童依恋理论中的陌生情景测试（Strange situation test）有所了解，那么也就能很快将知识迁移到成人依恋领域了。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
